constexpr int SGN = TG / 32;
constexpr int CPS = BN / SGN;
constexpr int NCH = CPS / CB;
const uint lane = thread_index_in_simdgroup;
const uint sgi = simdgroup_index_in_threadgroup;
const int K = x_shape[1];
const int n = gq_shape[0];
const int r = int(threadgroup_position_in_grid.y);
const int tile = int(threadgroup_position_in_grid.x);
const int KW = K >> 3;
const int KG = K >> 6;
const int units = K >> 5;
const int col0 = tile * BN + int(sgi) * CPS;
auto xr = x + r * K;
auto rr = res + r * K;
const float epsv = eps[0];
if (units <= 32) {
  const bool act = int(lane) < units;
  const int uu = act ? int(lane) : (units - 1);
  const float actf = act ? 1.0f : 0.0f;
  const int k0 = uu << 5;
  const int gi = uu >> 1;
  const int qo = uu << 2;
  uint4 cg[CB];
  uint4 cu[CB];
  float csg[CB], cbg[CB], csu[CB], cbu[CB];
  for (int c = 0; c < CB; ++c) {
    int j = min(col0 + c, n - 1);
    cg[c] = ldq4(gq + j * KW + qo);
    cu[c] = ldq4(uq + j * KW + qo);
    csg[c] = float(gs[j * KG + gi]);
    cbg[c] = float(gb[j * KG + gi]);
    csu[c] = float(us[j * KG + gi]);
    cbu[c] = float(ub[j * KG + gi]);
  }
  float xv[32];
  float rv[32];
  float wv[32];
  for (int q8 = 0; q8 < 4; ++q8) {
    ld8(xr + k0 + q8 * 8, &xv[q8 * 8]);
    ld8(rr + k0 + q8 * 8, &rv[q8 * 8]);
    ld8(w + k0 + q8 * 8, &wv[q8 * 8]);
  }
  float a[32];
  float asum = 0.0f;
  float ss = 0.0f;
  for (int i = 0; i < 32; ++i) {
    float h = (xv[i] + rv[i]) * actf;
    ss = fma(h, h, ss);
    float av = h * wv[i];
    asum += av;
    a[i] = av * QSCL[i & 7];
  }
  ss = simd_sum(ss);
  const float inv = 1.0f / sqrt(ss / float(K) + epsv);
  for (int ch = 0; ch < NCH; ++ch) {
    uint4 ng[CB];
    uint4 nu[CB];
    float nsg[CB], nbg[CB], nsu[CB], nbu[CB];
    if (ch + 1 < NCH) {
      for (int c = 0; c < CB; ++c) {
        int j = min(col0 + (ch + 1) * CB + c, n - 1);
        ng[c] = ldq4(gq + j * KW + qo);
        nu[c] = ldq4(uq + j * KW + qo);
        nsg[c] = float(gs[j * KG + gi]);
        nbg[c] = float(gb[j * KG + gi]);
        nsu[c] = float(us[j * KG + gi]);
        nbu[c] = float(ub[j * KG + gi]);
      }
    }
    for (int c = 0; c < CB; ++c) {
      float dg = 0.0f;
      float du = 0.0f;
      for (int wi = 0; wi < 4; ++wi) {
        uint wg = cg[c][wi];
        uint wu = cu[c][wi];
        for (int e = 0; e < 8; ++e) {
          uint m = 0xFu << (4 * e);
          dg = fma(a[wi * 8 + e], float(wg & m), dg);
          du = fma(a[wi * 8 + e], float(wu & m), du);
        }
      }
      float ag = fma(csg[c], dg, cbg[c] * asum);
      float au = fma(csu[c], du, cbu[c] * asum);
      float g = simd_sum(ag) * inv;
      float uv = simd_sum(au) * inv;
      int col = col0 + ch * CB + c;
      if (lane == 0 && col < n) {
        float sl = g / (1.0f + exp(-g));
        out[r * n + col] = T(sl * uv);
      }
    }
    if (ch + 1 < NCH) {
      for (int c = 0; c < CB; ++c) {
        cg[c] = ng[c]; cu[c] = nu[c];
        csg[c] = nsg[c]; cbg[c] = nbg[c]; csu[c] = nsu[c]; cbu[c] = nbu[c];
      }
    }
  }
} else {
  float ss = 0.0f;
  for (int k = int(lane); k < K; k += 32) {
    float h = float(xr[k]) + float(rr[k]);
    ss = fma(h, h, ss);
  }
  ss = simd_sum(ss);
  const float inv = 1.0f / sqrt(ss / float(K) + epsv);
  for (int ch = 0; ch < NCH; ++ch) {
    int qoff[CB];
    int soff[CB];
    float accg[CB];
    float accu[CB];
    for (int c = 0; c < CB; ++c) {
      int j = min(col0 + ch * CB + c, n - 1);
      qoff[c] = j * KW;
      soff[c] = j * KG;
      accg[c] = 0.0f;
      accu[c] = 0.0f;
    }
    for (int u = int(lane); u < units; u += 32) {
      const int k0 = u << 5;
      const int gi = u >> 1;
      uint4 qg[CB];
      uint4 qu[CB];
      float sgv[CB], bgv[CB], suv[CB], buv[CB];
      for (int c = 0; c < CB; ++c) {
        qg[c] = ldq4(gq + qoff[c] + (u << 2));
        qu[c] = ldq4(uq + qoff[c] + (u << 2));
        sgv[c] = float(gs[soff[c] + gi]);
        bgv[c] = float(gb[soff[c] + gi]);
        suv[c] = float(us[soff[c] + gi]);
        buv[c] = float(ub[soff[c] + gi]);
      }
      float xv[32];
      float rv[32];
      float wv[32];
      for (int q8 = 0; q8 < 4; ++q8) {
        ld8(xr + k0 + q8 * 8, &xv[q8 * 8]);
        ld8(rr + k0 + q8 * 8, &rv[q8 * 8]);
        ld8(w + k0 + q8 * 8, &wv[q8 * 8]);
      }
      float a[32];
      float asum = 0.0f;
      for (int i = 0; i < 32; ++i) {
        float h = xv[i] + rv[i];
        float av = h * wv[i];
        asum += av;
        a[i] = av * QSCL[i & 7];
      }
      for (int c = 0; c < CB; ++c) {
        float dg = 0.0f;
        float du = 0.0f;
        for (int wi = 0; wi < 4; ++wi) {
          uint wg = qg[c][wi];
          uint wu = qu[c][wi];
          for (int e = 0; e < 8; ++e) {
            uint m = 0xFu << (4 * e);
            dg = fma(a[wi * 8 + e], float(wg & m), dg);
            du = fma(a[wi * 8 + e], float(wu & m), du);
          }
        }
        accg[c] = fma(sgv[c], dg, fma(bgv[c], asum, accg[c]));
        accu[c] = fma(suv[c], du, fma(buv[c], asum, accu[c]));
      }
    }
    for (int c = 0; c < CB; ++c) {
      float g = simd_sum(accg[c]) * inv;
      float uv = simd_sum(accu[c]) * inv;
      int col = col0 + ch * CB + c;
      if (lane == 0 && col < n) {
        float sl = g / (1.0f + exp(-g));
        out[r * n + col] = T(sl * uv);
      }
    }
  }
}

