constant float QSCL[8] = {1.0f, 0.0625f, 0.00390625f, 0.000244140625f, 1.52587890625e-05f, 9.5367431640625e-07f, 5.9604644775390625e-08f, 3.7252902984619141e-09f};
inline uint4 ldq4(const device uint32_t* p) { return *reinterpret_cast<const device uint4*>(p); }
inline uint4 ldq4(const constant uint32_t* p) { return *reinterpret_cast<const constant uint4*>(p); }
template <typename P> inline void ld8(P p, thread float* o) { for (int i = 0; i < 8; ++i) { o[i] = float(p[i]); } }
inline void ld8(const device half* p, thread float* o) {
  uint4 t = *reinterpret_cast<const device uint4*>(p);
  half2 a0 = as_type<half2>(t.x); half2 a1 = as_type<half2>(t.y); half2 a2 = as_type<half2>(t.z); half2 a3 = as_type<half2>(t.w);
  o[0] = float(a0.x); o[1] = float(a0.y); o[2] = float(a1.x); o[3] = float(a1.y);
  o[4] = float(a2.x); o[5] = float(a2.y); o[6] = float(a3.x); o[7] = float(a3.y);
}
inline void ld8(const constant half* p, thread float* o) {
  uint4 t = *reinterpret_cast<const constant uint4*>(p);
  half2 a0 = as_type<half2>(t.x); half2 a1 = as_type<half2>(t.y); half2 a2 = as_type<half2>(t.z); half2 a3 = as_type<half2>(t.w);
  o[0] = float(a0.x); o[1] = float(a0.y); o[2] = float(a1.x); o[3] = float(a1.y);
  o[4] = float(a2.x); o[5] = float(a2.y); o[6] = float(a3.x); o[7] = float(a3.y);
}
inline void ld8(const device float* p, thread float* o) {
  float4 a = *reinterpret_cast<const device float4*>(p);
  float4 b = *reinterpret_cast<const device float4*>(p + 4);
  o[0] = a.x; o[1] = a.y; o[2] = a.z; o[3] = a.w; o[4] = b.x; o[5] = b.y; o[6] = b.z; o[7] = b.w;
}
inline void ld8(const constant float* p, thread float* o) {
  float4 a = *reinterpret_cast<const constant float4*>(p);
  float4 b = *reinterpret_cast<const constant float4*>(p + 4);
  o[0] = a.x; o[1] = a.y; o[2] = a.z; o[3] = a.w; o[4] = b.x; o[5] = b.y; o[6] = b.z; o[7] = b.w;
}
